custom_css:
/* ==========================================================
   MoodTube theme: Paper Sleeve  (theme format v2)
   Black & white editorial collage: off-white paper, a black vinyl
   peeking out of a white sleeve, paper-cut music notes, a heavy
   gradient "MUSIC!!" heading, pixel track title and pill buttons.
   Two layouts (container query): "sleeve" for the portrait size,
   a plain paper bar for any other size.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Anton&family=Silkscreen:wght@400;700&family=Inter:wght@400;500;600&display=swap');

@keyframes ps-spin { to { transform: rotate(360deg); } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --ps-paper: #f4f4f2;
    --ps-sleeve: #fcfcfb;
    --ps-line: #d5d5d0;
    --ps-ink: #111111;
    --ps-dim: #777777;
    --mt-text: var(--ps-ink);
    --mt-text-dim: var(--ps-dim);
    --mt-text-on-accent: #ffffff;
}

/* ---------- Sliders ---------- */
.mt-progress {
    --mt-slider-track: radial-gradient(circle, #c9c9c5 2.2px, transparent 2.7px) 0 50% / 10px 8px repeat-x;
    --mt-slider-track-height: 8px;
    --mt-slider-track-radius: 0;
    --mt-slider-thumb-size: 12px;
    --mt-slider-thumb-bg: var(--ps-ink);
    --mt-slider-thumb-bg-hover: #444444;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--ps-ink);
}
.mt-volume {
    --mt-slider-track: rgba(17, 17, 17, 0.25);
    --mt-slider-track-height: 1px;
    --mt-slider-track-radius: 0;
    --mt-slider-thumb-size: 9px;
    --mt-slider-thumb-bg: var(--ps-ink);
    --mt-slider-thumb-bg-hover: #444444;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--ps-ink);
}

/* ---------- Paper (all sizes) ---------- */
.mt-player {
    container-type: size;
    padding: 46px 16px 16px;
    background: var(--ps-paper);
    border: 1px solid var(--ps-line);
    border-radius: 8px;
    color: var(--ps-ink);
    font-family: 'Inter', 'Segoe UI', sans-serif;
    box-shadow: none;
    backdrop-filter: none; -webkit-backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }
.mt-slot-decor { display: none; }

/* heading: heavy condensed, grey-to-black gradient */
.mt-player-header { top: 10px; left: 16px; right: 82px; align-items: baseline; gap: 6px; }
.mt-player-header-title {
    font-family: 'Anton', Impact, sans-serif; font-size: 27px; font-weight: 400; line-height: 1; letter-spacing: 0.01em; text-transform: uppercase;
    background: linear-gradient(180deg, #2b2b2b 10%, #8d8d8d 100%); -webkit-background-clip: text; background-clip: text;
    color: transparent; -webkit-text-fill-color: transparent; flex-shrink: 0; overflow: visible;
}
.mt-player-status { color: var(--ps-dim); opacity: 1; font-size: 8.5px; letter-spacing: 0; }
.mt-window-btn {
    top: 14px; width: auto; height: auto; padding: 0; background: none; border: none;
    font-size: 13px; color: var(--ps-ink);
}
.mt-btn-search { right: 62px; }
.mt-btn-settings { right: 38px; }
.mt-btn-close { right: 14px; }
.mt-resize-handle i { color: rgba(17, 17, 17, 0.3); }

/* ---------- Vinyl ---------- */
.mt-player .mt-player-body { gap: 8px; }
.mt-cover {
    width: 54px; height: 54px; box-sizing: border-box; border: none; border-radius: 50%; box-shadow: none;
    background: repeating-radial-gradient(circle at 50% 50%, #0a0a0a 0 2px, #181818 2px 3px);
}
.mt-cover-img { width: 40%; height: 40%; flex: none; border: 3px solid #f3f3f0; box-sizing: border-box; background: #dcdcd8; }
.mt-cover-hole { z-index: 3; width: 6px; height: 6px; background: #0a0a0a; border: 1px solid #8a8a86; }
.mt-player.mt-is-playing .mt-cover-img { animation: ps-spin 8s linear infinite; }
.mt-cover::after {
    content: ''; position: absolute; inset: 0; z-index: 2; border-radius: 50%; pointer-events: none;
    background: conic-gradient(from 200deg, rgba(255, 255, 255, 0) 0deg, rgba(255, 255, 255, 0.13) 32deg, rgba(255, 255, 255, 0) 72deg,
                               rgba(255, 255, 255, 0) 180deg, rgba(255, 255, 255, 0.1) 212deg, rgba(255, 255, 255, 0) 252deg);
}

/* ---------- Track (pixel title on the sleeve) ---------- */
.mt-player .mt-track-info { align-items: flex-start; text-align: left; padding: 0 22px 0 0; }
.mt-player .mt-track-info > .mt-track-title {
    font-family: 'Silkscreen', 'Courier New', monospace; font-size: 14px; font-weight: 700; line-height: 1.15; letter-spacing: 0.01em;
    text-transform: uppercase; color: var(--ps-ink); margin: 0 0 4px; width: 100%;
}
.mt-track-subtitle { color: #555555; font-size: 8.5px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; }
.mt-btn-favorite { color: var(--ps-ink); font-size: 12px; right: 0; top: 2px; }

.mt-time { color: var(--ps-dim); font-size: 8px; font-weight: 500; letter-spacing: 0.06em; }
.mt-progress { margin-top: 0; }

/* ---------- Pill buttons ---------- */
.mt-controls { gap: 5px; }
.mt-controls > .mt-btn {
    width: 40px; height: 26px; box-sizing: border-box; display: flex; align-items: center; justify-content: center;
    font-size: 10px; color: var(--ps-ink); background: #ffffff; border: 1px solid var(--ps-ink); border-radius: 999px;
}
.mt-controls > .mt-btn-queue, .mt-controls > .mt-btn-ai { width: 26px; }
.mt-controls > .mt-btn-play {
    width: 58px; height: 30px; font-size: 12px; color: #ffffff;
    background: linear-gradient(180deg, #666666, #1c1c1c); border-color: #111111;
}
.mt-controls > .mt-btn:hover { transform: none; background: #ecece9; color: var(--ps-ink); }
.mt-controls > .mt-btn-play:hover { background: linear-gradient(180deg, #7a7a7a, #2a2a2a); color: #ffffff; }
.mt-btn-ai.mt-is-busy { background: var(--ps-ink); color: #ffffff; }
.mt-volume-icon { color: var(--ps-ink); font-size: 10px; }

/* wide bar */
.mt-player.moodtube-row-layout { padding-top: 34px; padding-bottom: 10px; }
.mt-player.moodtube-row-layout .mt-player-header { top: 8px; }
.mt-player.moodtube-row-layout .mt-player-header-title { font-size: 21px; }
.mt-player.moodtube-row-layout .mt-window-btn { top: 12px; }
.mt-player.moodtube-row-layout .mt-player-body { gap: 8px; }
.mt-player.moodtube-row-layout .mt-track-info { flex: 1 1 110px; min-width: 60px; padding-right: 18px; }
.mt-player.moodtube-row-layout .mt-track-title { font-size: 11px; }
.mt-player.moodtube-row-layout .mt-time-total { display: none; }
.mt-player.moodtube-row-layout .mt-progress { flex: 1 1 100px; min-width: 80px; }
.mt-player.moodtube-row-layout .mt-controls { gap: 3px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn { width: 32px; height: 22px; font-size: 9px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-queue, .mt-player.moodtube-row-layout .mt-controls > .mt-btn-ai { width: 22px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play { width: 44px; height: 26px; }
.mt-player.moodtube-row-layout .mt-volume { flex: 0 1 70px; min-width: 48px; }
.mt-player.moodtube-row-layout .mt-volume-high { display: none; }

/* narrow window */
@container (max-width: 200px) {
    .mt-player .mt-controls { gap: 3px; }
    .mt-player .mt-controls > .mt-btn { width: 30px; height: 24px; }
    .mt-player .mt-controls > .mt-btn-queue, .mt-player .mt-controls > .mt-btn-ai { width: 24px; }
    .mt-player .mt-controls > .mt-btn-play { width: 40px; height: 26px; }
}

/* ---------- Sleeve layout: the vinyl sticks out of a white sleeve ---------- */
@container (min-width: 214px) and (min-height: 276px) {
    .mt-player:not(.moodtube-row-layout) .mt-player-body { position: relative; gap: 8px; justify-content: flex-start; }

    .mt-player:not(.moodtube-row-layout) .mt-cover { width: 150px; height: 150px; z-index: 1; }
    .mt-player:not(.moodtube-row-layout) .mt-cover-img { width: 56px; height: 56px; border-width: 4px; }
    .mt-player:not(.moodtube-row-layout) .mt-cover-hole { width: 7px; height: 7px; }

    /* the sleeve itself: sits above the disc, below the text */
    .mt-player:not(.moodtube-row-layout) .mt-player-body::before {
        content: ''; position: absolute; z-index: 2; left: -6px; right: -6px; top: 104px; bottom: -8px;
        background: var(--ps-sleeve); border: 1px solid var(--ps-line); border-radius: 3px;
    }
    .mt-player:not(.moodtube-row-layout) .mt-track-info,
    .mt-player:not(.moodtube-row-layout) .mt-progress,
    .mt-player:not(.moodtube-row-layout) .mt-controls,
    .mt-player:not(.moodtube-row-layout) .mt-volume { position: relative; z-index: 3; }
    .mt-player:not(.moodtube-row-layout) .mt-track-info { margin-top: -44px; padding-left: 4px; }
    .mt-player:not(.moodtube-row-layout) .mt-track-info > .mt-track-title {
        display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; white-space: normal; overflow: hidden;
    }
    .mt-player:not(.moodtube-row-layout) .mt-progress { margin-top: 2px; }
    .mt-player:not(.moodtube-row-layout) .mt-volume { padding-right: 52px; box-sizing: border-box; }

    /* paper-cut notes (images.decor) and the round sticker */
    .mt-player:not(.moodtube-row-layout) .mt-slot-decor {
        display: block; background-size: 54px auto; background-position: 4px 56px; background-repeat: no-repeat;
    }
    .mt-player:not(.moodtube-row-layout) .mt-slot-decor::after {
        content: ''; position: absolute; right: 8px; bottom: 8px; width: 48px; height: 48px;
        background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2060%2060%27%3E%0A%3Ccircle%20cx%3D%2730%27%20cy%3D%2730%27%20r%3D%2728%27%20fill%3D%27%23111111%27%2F%3E%0A%3Ccircle%20cx%3D%2730%27%20cy%3D%2730%27%20r%3D%2724%27%20fill%3D%27none%27%20stroke%3D%27%23ffffff%27%20stroke-opacity%3D%270.35%27%20stroke-width%3D%271%27%20stroke-dasharray%3D%272%203%27%2F%3E%0A%3Cg%20fill%3D%27%23ffffff%27%3E%0A%3Cellipse%20cx%3D%2725%27%20cy%3D%2740%27%20rx%3D%276.5%27%20ry%3D%274.8%27%20transform%3D%27rotate(-22%2025%2040)%27%2F%3E%0A%3Crect%20x%3D%2729.5%27%20y%3D%2716%27%20width%3D%272.8%27%20height%3D%2724%27%2F%3E%0A%3Cpath%20d%3D%27M32%2016%20C39%2019%2043%2024%2041%2031%20C39%2027%2036%2025%2032%2024Z%27%2F%3E%0A%3C%2Fg%3E%0A%3Cpath%20d%3D%27M60%2040%20L40%2060%20L60%2060Z%27%20fill%3D%27%23e9e9e6%27%2F%3E%0A%3C%2Fsvg%3E") center / contain no-repeat;
    }
}

/* ---------- Queue / playlists ---------- */
.mt-panel { background: var(--ps-paper); padding-top: 46px; border-radius: inherit; }
.mt-panel-title { color: var(--ps-ink); font-family: 'Anton', Impact, sans-serif; font-size: 16px; font-weight: 400; letter-spacing: 0.03em; text-transform: uppercase; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--ps-ink); }
.mt-queue-item { background: #ffffff; border-color: var(--ps-line); border-radius: 6px; }
.mt-queue-item:hover { background: #ecece9; }
.mt-queue-item.mt-is-current { background: var(--ps-ink); border-color: var(--ps-ink); }
.mt-queue-thumb { border-radius: 50%; }
.mt-queue-thumb.mt-is-empty { background: #dcdcd8; }
.mt-queue-title, .mt-playlist-title { color: var(--ps-ink); }
.mt-queue-item.mt-is-current .mt-queue-title { color: #ffffff; }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #b3261e; }
.mt-queue-now, .mt-queue-add { color: var(--ps-ink); }
.mt-queue-item.mt-is-current .mt-queue-now { color: #ffffff; }
.mt-queue-dislike { background-color: var(--ps-ink); }
.mt-queue-item.mt-is-current .mt-queue-dislike { background-color: #ffffff; }
.mt-queue-empty { color: var(--ps-dim); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked { background: #ffffff; border-color: var(--ps-ink); box-shadow: none; color: var(--ps-ink); }

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: #111 transparent; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 6px; height: 6px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: transparent; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: #111; border-radius: 3px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(244, 244, 242, 0.7);
    --mt-modal-shadow: none;
    --mt-text-strong: #000000;
    --mt-divider: var(--ps-line);
}
#mt-settings-modal .mt-flex-container { border: 1px solid var(--ps-ink); border-radius: 8px; }
#mt-settings-modal .mt-header h3 { font-family: 'Anton', Impact, sans-serif; font-size: 1.5em; font-weight: 400; letter-spacing: 0.03em; text-transform: uppercase; }
#mt-settings-modal .mt-close { color: var(--ps-ink); }
#mt-settings-modal .mt-cat-title:hover { background-color: rgba(0, 0, 0, 0.04); }
#mt-settings-modal .mt-tag { background-color: #ffffff; border-color: var(--ps-ink); border-radius: 999px; box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover { background-color: #ecece9; border-color: var(--ps-ink); }
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active { background-color: var(--ps-ink); border-color: var(--ps-ink); box-shadow: none; }
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { border-radius: 999px; box-shadow: none; }
#mt-settings-modal .mt-input-field { border-radius: 6px; }
#mt-settings-modal .mt-btn-save { border-radius: 999px; background: linear-gradient(180deg, #666666, #1c1c1c); }
#mt-settings-modal .mt-btn-test { background: #ffffff; border-color: var(--ps-ink); border-radius: 999px; }
#mt-settings-modal .mt-btn-test:hover { background: #ecece9; }
#mt-settings-modal .mt-subpanel { background: rgba(0, 0, 0, 0.03); }

/* ---------- Search panel and playlists (added to the extension later) ---------- */

.mt-panel-search { --mt-bg-primary: #f4f4f2; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #fff) !important; border-radius: 999px !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--ps-ink); --mt-pl-spotify-tab-text: #ffffff; }
.mt-btn-favorite.mt-is-active { color: var(--ps-ink); }
.mt-pl-tabs { background: #ecece9; border-radius: 999px; }
.mt-pl-tab { color: var(--ps-dim); border-radius: 999px; }
.mt-pl-tool { background: #ffffff; border-color: var(--ps-ink); color: var(--ps-ink); border-radius: 999px; }
.mt-pl-tool:hover { background: #ecece9; }
.mt-pl-tool.mt-pl-play { background: linear-gradient(180deg, #666666, #1c1c1c); border-color: #111111; color: #ffffff; }
.mt-pl-inline-cancel { background: #ecece9; color: var(--ps-ink); }
.mt-pl-cover-empty { background: #dcdcd8; color: var(--ps-dim); }
.mt-pl-modal { --mt-overlay: rgba(244, 244, 242, 0.7); }
.mt-pl-modal-box { background: var(--ps-paper); border: 1px solid var(--ps-ink); border-radius: 8px; box-shadow: none; }
.mt-pl-modal-track { border-bottom-color: var(--ps-line); }
.mt-pl-modal-title { font-family: 'Anton', Impact, sans-serif; font-size: 16px; font-weight: 400; letter-spacing: 0.03em; text-transform: uppercase; }
.mt-pl-option { background: #ffffff; border: 1px solid var(--ps-line); }
.mt-pl-option:hover { background: #ecece9; }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--ps-ink); }

/* ---------- Theme catalog in the settings window ---------- */
#mt-settings-modal .mt-catalog-preview { background: #dcdcd8; color: var(--ps-dim); }
#mt-settings-modal .mt-catalog-tag { background: #ecece9; color: var(--ps-dim); border-radius: 999px; }
#mt-settings-modal .mt-catalog-item { border-radius: 8px; }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  --mt-dock-cover-radius: 4px;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 4px;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-window-btn.mt-btn-lyrics { right: 86px; }
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 8px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 6px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 38px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 70px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 102px; left: auto; }
/* == /window buttons == */
